CREATE OR REPLACE FUNCTION is_room_member(check_room_id uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM chat_participants WHERE room_id = check_room_id AND user_id = auth.uid()); $$; DROP POLICY IF EXISTS "Users can see participants in their rooms" ON public.chat_participants; CREATE POLICY "Users can see participants in their rooms" ON public.chat_participants FOR SELECT USING (is_room_member(room_id));
